<template><BtgPageContainer as="article" aria-labelledby="certificate-title"><div v-if="state==='loading'" role="status"><h1 id="certificate-title">Loading certificate…</h1></div><div v-else-if="state==='missing'"><h1 id="certificate-title">Certificate unavailable</h1></div><div v-else-if="state==='error'" role="alert"><h1 id="certificate-title">Certificate unavailable</h1><BtgButton @click="load">Try again</BtgButton></div><template v-else><h1 id="certificate-title">{{ certificate.achievement.title }}</h1><p role="status">{{ certificate.status==='ACTIVE'?'This certificate is recorded as active.':'This certificate has been revoked.' }}</p><dl><div><dt>Version</dt><dd>{{ certificate.achievement.version }}</dd></div><div><dt>Language</dt><dd>{{ certificate.achievement.language }}</dd></div><div><dt>Issued</dt><dd><time :datetime="certificate.issuedAt">{{ format(certificate.issuedAt) }}</time></dd></div><div><dt>Issuer</dt><dd>{{ certificate.issuer.name }}</dd></div><div><dt>Criteria</dt><dd>{{ certificate.achievement.criteria }}</dd></div></dl><RouterLink :to="verificationPath(certificate.certificateId)">Open public verification</RouterLink><a v-if="certificate.openBadgePath" :href="certificate.openBadgePath">Open signed Open Badge credential</a></template></BtgPageContainer></template><script setup lang="ts">import{ref,watch}from'vue';import{useRoute}from'vue-router';import{APIProblemError}from'../api/client';import BtgPageContainer from'../components/BtgPageContainer.vue';import BtgButton from'../components/BtgButton.vue';import{getLearnerCertificate,verificationPath,type LearnerCertificate}from'../courses/certificates';const route=useRoute(),state=ref('loading'),certificate=ref<LearnerCertificate>({} as LearnerCertificate);let generation=0;watch(()=>route.params.certificateId,load,{immediate:true});async function load(){const id=String(route.params.certificateId||''),n=++generation;state.value='loading';try{const x=await getLearnerCertificate(id);if(n!==generation)return;certificate.value=x;state.value='ready'}catch(e){if(n!==generation)return;state.value=e instanceof APIProblemError&&e.status===404?'missing':'error'}}function format(v:string){return new Intl.DateTimeFormat('en',{dateStyle:'medium'}).format(new Date(v))}</script>
